    private function publishDistribution($user,$id){
        if((int)$this->scalar("SELECT COUNT(*) FROM product_distributions WHERE id={$id} AND status='draft'")!==1)jsonResponse(array('success'=>false,'message'=>'Phân bố không tồn tại hoặc đã được phát hành.'),409);
        $items=$this->rows("SELECT product_id,opening_stock FROM product_distribution_items WHERE distribution_id={$id}");$theaters=$this->rows("SELECT theater_id FROM product_distribution_theaters WHERE distribution_id={$id}");if(!$items||!$theaters)jsonResponse(array('success'=>false,'message'=>'Phân bố chưa có hàng hóa hoặc rạp nhận.'),422);
        $actor=(int)$user['id'];$actorName=$this->db->real_escape_string($user['full_name']);$this->db->query('START TRANSACTION');
        if(!$this->db->query("UPDATE product_distributions SET status='published',published_by={$actor},published_by_name='{$actorName}',published_at=NOW(),updated_at=NOW() WHERE id={$id} AND status='draft'")||$this->db->affected_rows!==1){$this->db->query('ROLLBACK');jsonResponse(array('success'=>false,'message'=>'Phân bố vừa được xử lý ở phiên khác.'),409);}
        if(!$this->db->query("UPDATE product_distribution_theaters SET status='published',published_at=NOW() WHERE distribution_id={$id}")||!$this->db->query("UPDATE products p INNER JOIN product_distribution_items di ON di.product_id=p.id SET p.status='active',p.updated_at=NOW() WHERE di.distribution_id={$id}")){ $this->db->query('ROLLBACK');jsonResponse(array('success'=>false,'message'=>'Không thể phát hành phân bố hàng hóa.'),500); }
        try{foreach($theaters as $theaterRow)foreach($items as $item){$theater=(int)$theaterRow['theater_id'];$product=(int)$item['product_id'];$stock=(int)$item['opening_stock'];$before=(int)$this->scalar("SELECT stock_quantity FROM theater_product_inventory WHERE theater_id={$theater} AND product_id={$product} LIMIT 1");$after=$before+$stock;if(!$this->db->query("INSERT INTO theater_product_inventory(theater_id,product_id,stock_quantity,reorder_level,last_distribution_id,updated_at) VALUES({$theater},{$product},{$stock},GREATEST(5,CEIL({$stock}*0.1)),{$id},NOW()) ON DUPLICATE KEY UPDATE stock_quantity=stock_quantity+VALUES(stock_quantity),reorder_level=VALUES(reorder_level),last_distribution_id={$id},updated_at=NOW()"))throw new Exception($this->db->error);if(!$this->db->query("INSERT INTO product_inventory_movements(theater_id,product_id,distribution_id,movement_type,quantity,stock_before,stock_after,reference_code,performed_by,performed_by_name,created_at) VALUES({$theater},{$product},{$id},'DISTRIBUTION',{$stock},{$before},{$after},'PB-{$id}',{$actor},'{$actorName}',NOW())"))throw new Exception($this->db->error);}}catch(Exception $error){$this->db->query('ROLLBACK');jsonResponse(array('success'=>false,'message'=>'Không thể cấp hàng vào rạp: '.$error->getMessage()),500);}
        $this->db->query("UPDATE products p SET p.stock_quantity=(SELECT COALESCE(SUM(inv.stock_quantity),0) FROM theater_product_inventory inv WHERE inv.product_id=p.id) WHERE p.id IN (SELECT product_id FROM product_distribution_items WHERE distribution_id={$id})");
        if(!$this->db->query('COMMIT'))jsonResponse(array('success'=>false,'message'=>'Không thể hoàn tất phát hành phân bố.'),500);
        if(function_exists('writeTmsAuditLog'))writeTmsAuditLog($this->db,'PUBLISH_PRODUCT_DISTRIBUTION','Phát hành phân bố hàng hóa đến rạp và đồng bộ POS.',array('module'=>'operations','entity_type'=>'product_distribution','entity_id'=>$id,'severity'=>'success','metadata'=>array('theater_count'=>count($theaters),'item_count'=>count($items))));
        jsonResponse(array('success'=>true,'message'=>'Đã phân bố hàng hóa đến rạp. Danh mục và tồn đầu kỳ đã sẵn sàng trên POS.'));
    }

