    private function sendPlan($user,$id) {
        $row=$this->rows("SELECT status FROM product_plans WHERE id={$id} LIMIT 1");if(!$row||$row[0]['status']!=='draft')jsonResponse(array('success'=>false,'message'=>'Kế hoạch không tồn tại hoặc đã được gửi.'),409);if(!(int)$this->scalar("SELECT COUNT(*) FROM product_plan_items WHERE plan_id={$id}")||!(int)$this->scalar("SELECT COUNT(*) FROM product_plan_theaters WHERE plan_id={$id}")||(int)$this->scalar("SELECT COUNT(*) FROM product_plan_items WHERE plan_id={$id} AND monthly_sales_target<1")>0)jsonResponse(array('success'=>false,'message'=>'Kế hoạch chưa có hàng hóa, mục tiêu bán tháng hoặc rạp thực hiện hợp lệ.'),422);
        $actor=(int)$user['id'];$name=$this->db->real_escape_string($user['full_name']);$this->db->query('START TRANSACTION');if(!$this->db->query("UPDATE product_plans SET status='sent',sent_by={$actor},sent_by_name='{$name}',sent_at=NOW(),updated_at=NOW() WHERE id={$id} AND status='draft'")||$this->db->affected_rows!==1){$this->db->query('ROLLBACK');jsonResponse(array('success'=>false,'message'=>'Kế hoạch vừa được xử lý ở phiên khác.'),409);}if(!$this->db->query("UPDATE product_plan_theaters SET status='sent',sent_at=NOW() WHERE plan_id={$id}")){ $this->db->query('ROLLBACK');jsonResponse(array('success'=>false,'message'=>'Không thể gửi kế hoạch đến rạp.'),500);}if(!$this->db->query('COMMIT'))jsonResponse(array('success'=>false,'message'=>'Không thể hoàn tất gửi kế hoạch.'),500);if(function_exists('writeTmsAuditLog'))writeTmsAuditLog($this->db,'SEND_PRODUCT_KPI_PLAN','Gửi kế hoạch KPI bán hàng đến Admin Rạp.',array('module'=>'operations','entity_type'=>'product_plan','entity_id'=>$id,'severity'=>'success'));jsonResponse(array('success'=>true,'message'=>'Đã gửi kế hoạch KPI bán hàng. Danh mục và tồn kho POS không bị thay đổi.'));
    }

    private function acknowledge($user,$id,$input) {
        if($user['role']!=='cinema_admin')jsonResponse(array('success'=>false,'message'=>'Chỉ Admin Rạp được xác nhận đã nắm kế hoạch.'),403);$theater=(int)$user['theater_id'];if($theater<1)jsonResponse(array('success'=>false,'message'=>'Tài khoản chưa được gán rạp.'),409);$note=$this->db->real_escape_string(trim(isset($input['response_note'])?(string)$input['response_note']:''));$actor=(int)$user['id'];$name=$this->db->real_escape_string($user['full_name']);if(!$this->db->query("UPDATE product_plan_theaters SET status='acknowledged',acknowledged_by={$actor},acknowledged_by_name='{$name}',acknowledged_at=NOW(),response_note='{$note}' WHERE plan_id={$id} AND theater_id={$theater} AND status='sent'")||$this->db->affected_rows!==1)jsonResponse(array('success'=>false,'message'=>'Kế hoạch không tồn tại, đã xác nhận hoặc không thuộc rạp của bạn.'),409);jsonResponse(array('success'=>true,'message'=>'Đã xác nhận rạp nắm thông tin kế hoạch hàng hóa.'));
    }
}
